mapper.select:
SELECT fi.*, fc.name AS categoryName, fs.name AS shopName FROM food_info fi LEFT JOIN food_category fc ON fi.category_id = fc.id LEFT JOIN food_shop fs ON fi.shop_id = fs.id
AND (fi.name LIKE CONCAT('%', #{params.keyword}, '%') OR fi.description LIKE CONCAT('%', #{params.keyword}, '%'))
AND fi.category_id = #{params.categoryId}
AND fi.shop_id = #{params.shopId}
AND fi.is_recommend = #{params.isRecommend}
AND fi.status = #{params.status}
ORDER BY fi.is_recommend DESC, fi.create_time DESC
